```sql
SELECT
    COALESCE(SUM(oi.quantity * oi.unit_price), 0) AS gross_value,
    COUNT(DISTINCT o.customer_id) AS customer_count
FROM
    orders o
JOIN
    order_items oi ON o.order_id = oi.order_id
WHERE
    o.status = 'placed'
AND
    o.order_date LIKE '2024-%'
AND
    o.customer_id IN (
        SELECT
            customer_id
        FROM
            customers
        WHERE
            city = 'Delhi'
    )
GROUP BY
    o.customer_id
ORDER BY
    customer_count DESC;
```

